// src/components/Admin/AddProduct.js
import React, { useState } from 'react';
import './AddProduct.css';

function AddProduct({ addProduct }) {
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    averagePreparationTime: '',
    category: 'Pizza',
    stock: '',
    image: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.name && formData.price && formData.category && formData.averagePreparationTime) {
      addProduct({
        ...formData,
        price: parseFloat(formData.price),
        averagePreparationTime: parseInt(formData.averagePreparationTime, 10),
        stock: parseInt(formData.stock, 10) || 0,
        image: formData.image || 'https://via.placeholder.com/150/EEEEEE/808080?text=No+Image'
      });
      
      setFormData({
        name: '',
        description: '',
        price: '',
        averagePreparationTime: '',
        category: 'Pizza',
        stock: '',
        image: ''
      });
      
      alert('Product added successfully!');
    } else {
      alert('Please fill in all required fields (*).');
    }
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  return (
    <div className="add-product-container">
      <h1>Add New Product</h1>

      <form onSubmit={handleSubmit} className="product-form">
        
        <div className="form-grid">
            
            {/* LEFT COLUMN: Image Placeholder */}
            <div className="image-column">
                <div className="image-placeholder-box">
                    <span>+ Add Image</span>
                    
                    {/* Hidden file input for actual image upload, controlled by JavaScript */}
                    <input type="file" style={{ display: 'none' }} />
                </div>
            </div>

            {/* RIGHT COLUMN: Form Fields */}
            <div className="fields-column">
                
                {/* Product Name and Price (Side by Side) */}
                <div className="input-row">
                    <div className="form-group half-width">
                        <label>Product Name *</label>
                        <input type="text" name="name" value={formData.name} onChange={handleChange} required />
                    </div>
                    <div className="form-group half-width">
                        <label>Price (₹) *</label>
                        <input type="number" name="price" value={formData.price} onChange={handleChange} required />
                    </div>
                </div>

                {/* Category and Preparation Time (Side by Side) */}
                <div className="input-row">
                    <div className="form-group half-width">
                        <label>Category *</label>
                        <select name="category" value={formData.category} onChange={handleChange} required>
                            <option>Pizza</option>
                            <option>Burger</option>
                            <option>Drink</option>
                            <option>French fries</option>
                            <option>Veggies</option>
                        </select>
                    </div>
                    <div className="form-group half-width">
                        <label>Avg. Prep Time (mins) *</label>
                        <input type="number" name="averagePreparationTime" value={formData.averagePreparationTime} onChange={handleChange} required />
                    </div>
                </div>
                
                {/* Stock and Image URL (Side by Side - Stock is optional) */}
                <div className="input-row">
                    <div className="form-group half-width">
                        <label>Stock (units)</label>
                        <input type="number" name="stock" value={formData.stock} onChange={handleChange} />
                    </div>
                    {/* We'll use this spot for the Image URL input, replacing the hidden file input */}
                    <div className="form-group half-width">
                        <label>Image URL (optional)</label>
                        <input type="text" name="image" value={formData.image} onChange={handleChange} placeholder="http://..." />
                    </div>
                </div>


                {/* Description (Full Width) */}
                <div className="form-group full-width">
                    <label>Description</label>
                    <input type="text" name="description" value={formData.description} onChange={handleChange} />
                </div>
            </div>

        </div>
        
        {/* Actions Row */}
        <div className="form-actions-row">
            <button type="button" className="action-btn cancel-btn">Cancel</button>
            <button type="submit" className="action-btn submit-btn">Save</button>
        </div>

      </form>
    </div>
  );
}

export default AddProduct;
